const NAME2ISO = (function(){
  const m={};
  Object.keys(GEO).forEach(set=>{
    const f=GEO[set].f;
    Object.keys(f).forEach(iso=>{
      m[iso.toUpperCase()]=iso;
      m[String(f[iso].n||"").toUpperCase()]=iso;
    });
  });
  // a few common alternates people actually type
  const alt={
    "DR CONGO":"COD","DRC":"COD","CONGO-KINSHASA":"COD","DEMOCRATIC REPUBLIC OF THE CONGO":"COD",
    "CONGO-BRAZZAVILLE":"COG","REPUBLIC OF THE CONGO":"COG",
    "IVORY COAST":"CIV","COTE D'IVOIRE":"CIV","CÔTE D'IVOIRE":"CIV",
    "THE GAMBIA":"GMB","GAMBIA":"GMB","CABO VERDE":"CPV","CAPE VERDE":"CPV",
    "TANZANIA":"TZA","UNITED REPUBLIC OF TANZANIA":"TZA",
    "USA":"USA","UNITED STATES":"USA","UNITED STATES OF AMERICA":"USA","US":"USA",
    "UK":"GBR","UNITED KINGDOM":"GBR","BRITAIN":"GBR","GREAT BRITAIN":"GBR",
    "SOUTH KOREA":"KOR","NORTH KOREA":"PRK","UAE":"ARE","SWAZILAND":"SWZ","ESWATINI":"SWZ",
    "SOUTH AFRICA":"ZAF","EGYPT":"EGY","ETHIOPIA":"ETH","MOROCCO":"MAR","KENYA":"KEN",
  };
  Object.keys(alt).forEach(k=>{ if(!m[k]) m[k]=alt[k]; });
  return m;
})();
function toIso(label){
  const k=String(label==null?"":label).trim().toUpperCase();
  return NAME2ISO[k]||null;
}

/* Equirectangular with a single uniform scale — no distortion, north up. */
function project(lon,lat,b,VW,VH,pad){
  const [x0,y0,x1,y1]=b;
  const w=VW-pad*2, h=VH-pad*2;
  const s=Math.min(w/Math.max(1e-6,(x1-x0)), h/Math.max(1e-6,(y1-y0)));
  const ox=pad+(w-(x1-x0)*s)/2, oy=pad+(h-(y1-y0)*s)/2;
  return [ox+(lon-x0)*s, oy+(y1-lat)*s];
}
function ringPath(ring,b,VW,VH,pad){
  let d="";
  for(let i=0;i<ring.length;i++){
    const p=project(ring[i][0],ring[i][1],b,VW,VH,pad);
    d+=(i?"L":"M")+p[0].toFixed(1)+" "+p[1].toFixed(1);
  }
  return d+"Z";
}

/* ── the gradient legend, shared by the choropleth and standalone ──── */
function buildLegend(el,stops,lo,hi,VW,VH,opts){
  const o=opts||{};
  const g=svg("g",{class:"hs-legend"});
  const x=num(o.x,54), y=num(o.y,VH*0.16);
  const bw=num(o.w,26), bh=num(o.h,VH*0.46);
  const fs=num(el.labelSize,26);

  // The bar is drawn as a stack of thin rects so it exports to a flat
  // SVG/PNG without depending on gradient support downstream.
  const steps=48;
  for(let i=0;i<steps;i++){
    const t=i/(steps-1);
    g.appendChild(svg("rect",{
      x, y:y+bh-(t+1/steps)*bh, width:bw, height:bh/steps+0.7,
      fill:rampAt(stops,t), stroke:"none"
    }));
  }
  g.appendChild(svg("rect",{x,y,width:bw,height:bh,fill:"none",stroke:"rgba(15,23,42,.18)","stroke-width":1.2,rx:3}));

  if(el.legendTitle){
    const t=svgText(x, y-fs*0.9, el.legendTitle, {class:"hs-legend-title","font-size":fs*0.74});
    g.appendChild(t);
  }
  // scale ticks
  const ticks=clamp(num(el.legendTicks,5),2,9);
  for(let i=0;i<ticks;i++){
    const t=i/(ticks-1), v=lo+(hi-lo)*t;
    const ly=y+bh-t*bh;
    g.appendChild(svg("line",{x1:x-6,y1:ly,x2:x,y2:ly,stroke:"rgba(15,23,42,.35)","stroke-width":1.2}));
    g.appendChild(svgText(x-10, ly+fs*0.26, fmtNum(v,el), {class:"hs-legend-tick","text-anchor":"end","font-size":fs*0.62}));
  }
  // benchmark markers — the "USA 5.1% / Europe 4.2%" ticks on the reference
  (Array.isArray(el.benchmarks)?el.benchmarks:[]).forEach(bm=>{
    const v=num(bm.value,NaN);
    if(!isFinite(v)) return;
    const t=clamp((v-lo)/Math.max(1e-9,(hi-lo)),0,1);
    const ly=y+bh-t*bh;
    g.appendChild(svg("line",{x1:x+bw,y1:ly,x2:x+bw+18,y2:ly,stroke:bm.color||el.accent||"#0f172a","stroke-width":2.4,"stroke-linecap":"round"}));
    g.appendChild(svgText(x+bw+24, ly+fs*0.26, (bm.label||"")+" "+fmtNum(v,el),
      {class:"hs-legend-bm","font-size":fs*0.62, fill:bm.color||el.accent||"#0f172a"}));
  });
  return g;
}

/* ════════════════════════════════════════════════════════════════════
   1. CHOROPLETH — countries shaded by value, with chips and a legend
   ════════════════════════════════════════════════════════════════════ */
function renderChoropleth(el){
  const setKey = GEO[el.geoSet] ? el.geoSet : "africa";
  const set = GEO[setKey];
  const box = div("hs-box hs-choropleth"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#1d4e89");

  const {VW,VH}=viewBox(el,1000,0.42,1.5);
  const pad=num(el.mapPad,52);
  const S=svg("svg",{viewBox:`0 0 ${VW} ${VH}`,preserveAspectRatio:"xMidYMid meet",class:"hs-svg"});
  const fs=num(el.labelSize,26);
  S.style.setProperty("--fs",fs+"px");

  const data=rows(el);
  const byIso={};
  data.forEach(r=>{ const iso=toIso(r.label); if(iso) byIso[iso]=r; });

  const vals=Object.keys(byIso).map(k=>byIso[k].value);
  const autoLo = el.scaleMin===""||el.scaleMin==null;
  const autoHi = el.scaleMax===""||el.scaleMax==null;
  let lo = autoLo ? Math.min.apply(null,vals.concat([Infinity])) : num(el.scaleMin,0);
  let hi = autoHi ? Math.max.apply(null,vals.concat([-Infinity])) : num(el.scaleMax,100);
  // Benchmark markers are drawn against this scale, so an automatic range
  // has to reach them. Without this, a benchmark below the lowest data
  // point pins to the floor and every such marker stacks on one line.
  (Array.isArray(el.benchmarks)?el.benchmarks:[]).forEach(bm=>{
    const v=num(bm.value,NaN);
    if(!isFinite(v))return;
    if(autoLo) lo=Math.min(lo,v);
    if(autoHi) hi=Math.max(hi,v);
  });
  if(!isFinite(lo)||!isFinite(hi)||lo===hi){ lo=0; hi=Math.max(1,isFinite(hi)?hi:100); }
  // A scale that starts just under the lowest value exaggerates small
  // differences; rounding the floor down to zero is the honest default.
  if(autoLo && lo>0 && lo < (hi-lo)) lo=0;

  const stops=rampFor(el);
  const baseFill = el.dark?"#1e293b":(el.baseFill||"#e8edf3");
  const border   = el.dark?"rgba(255,255,255,.14)":(el.borderColor||"#ffffff");

  // Legend occupies a left gutter; the map is offset to clear it.
  const showLegend = el.showLegend!==false;
  const gutter = showLegend? num(el.legendGutter,190) : 0;
  const mapG=svg("g",{class:"hs-map",transform:`translate(${gutter},0)`});
  const mw=VW-gutter;

  // Every country in the set is drawn — unmatched ones in the base tint,
  // which is what makes a shaded country read as a highlight.
  const isoList=Object.keys(set.f);
  isoList.forEach((iso,i)=>{
    const feat=set.f[iso], hit=byIso[iso];
    const t = hit ? clamp((hit.value-lo)/Math.max(1e-9,(hi-lo)),0,1) : null;
    const fill = hit ? (hit.color||rampAt(stops,t)) : baseFill;
    feat.r.forEach(ring=>{
      const p=svg("path",{
        d:ringPath(ring,set.b,mw,VH,pad),
        fill, stroke:border, "stroke-width":num(el.borderW,1.1),
        class:"hs-country"+(hit?" hs-country-hit":""),
        style:`--i:${i}`
      });
      if(hit) p.appendChild(svg("title",{})).textContent=feat.n+": "+fmtNum(hit.value,el);
      mapG.appendChild(p);
    });
  });

  // Value chips over each shaded country.
  //
  // Countries do not space themselves out for our convenience: Ghana sits
  // beside Nigeria, Kenya beside Ethiopia, and their chips collide at any
  // useful type size. So chips are laid out in two passes — measure and
  // anchor first, then relax overlaps apart — and any chip pushed off its
  // country gets a leader line back to it.
  if(el.showChips!==false){
    const style = el.chipStyle||"plain";       // plain | pill | bubble
    const chips = Object.keys(byIso).map((iso,i)=>{
      const feat=set.f[iso];
      if(!feat||!feat.c) return null;
      const r=byIso[iso];
      const [ax,ay]=project(feat.c[0],feat.c[1],set.b,mw,VH,pad);
      // Prefer what the user typed — someone who writes "DR Congo" should
      // not get "Dem. Rep. Congo" back — unless they typed a bare ISO code,
      // in which case the official name is the readable one.
      const typed = String(r.label||"").trim();
      const isCode = /^[A-Za-z]{3}$/.test(typed);
      const label = el.chipName===false ? "" : (r.note || (isCode?feat.n:typed) || feat.n);
      const value = fmtNum(r.value,el);
      return {
        i, iso, row:r, label, value, ax, ay,
        x:ax+num(r.dx,0), y:ay+num(r.dy,0),
        w:Math.max(value.length*1.14, label.length*0.72)*fs*0.58+fs*0.9,
        h:(label?fs*2.05:fs*1.3)
      };
    }).filter(Boolean);

    // Relaxation. Vertical-only separation keeps each chip over or near
    // its own country instead of drifting across the continent.
    if(el.chipDeclutter!==false){
      const gapY=fs*0.58;
      for(let pass=0; pass<90; pass++){
        let moved=false;
        for(let a=0;a<chips.length;a++){
          for(let b=a+1;b<chips.length;b++){
            const A=chips[a],B=chips[b];
            const ox=(A.w+B.w)/2-Math.abs(A.x-B.x);
            const oy=(A.h+B.h)/2+gapY-Math.abs(A.y-B.y);
            if(ox>0&&oy>0){
              const push=Math.min(oy/2, fs*0.5);
              if(A.y<=B.y){A.y-=push;B.y+=push;} else {A.y+=push;B.y-=push;}
              moved=true;
            }
          }
        }
        if(!moved)break;
      }
      chips.forEach(c=>{ c.y=clamp(c.y, c.h/2+4, VH-c.h/2-4); });
    }

    chips.forEach(c=>{
      const g=svg("g",{class:"hs-chip",style:`--i:${c.i}`});
      const vc = el.chipColor || (el.dark?"#ffffff":"#0f2f4f");

      // Leader line back to the country, when the chip had to move.
      const drift=Math.abs(c.y-c.ay);
      if(drift>c.h*0.45){
        g.appendChild(svg("line",{
          x1:c.x, y1:c.y+(c.y>c.ay?-c.h*0.42:c.h*0.42), x2:c.ax, y2:c.ay,
          stroke:el.dark?"rgba(255,255,255,.42)":"rgba(15,42,66,.34)",
          "stroke-width":1.4, "stroke-linecap":"round"
        }));
        g.appendChild(svg("circle",{cx:c.ax,cy:c.ay,r:2.6,
          fill:el.dark?"rgba(255,255,255,.6)":"rgba(15,42,66,.5)"}));
      }
      if(style==="pill"||style==="bubble"){
        g.appendChild(svg("rect",{
          x:c.x-c.w/2, y:c.y-c.h/2, width:c.w, height:c.h,
          rx: style==="bubble"?c.h/2:10,
          fill:el.dark?"rgba(2,6,23,.86)":"rgba(255,255,255,.94)",
          stroke:el.accent||"#1d4e89","stroke-width":1.6
        }));
      }
      g.appendChild(svgText(c.x, c.y+(c.label?-fs*0.12:fs*0.36), c.value,
        {class:"hs-chip-value","text-anchor":"middle","font-size":fs*1.14,fill:vc}));
      if(c.label) g.appendChild(svgText(c.x, c.y+fs*0.94, c.label,
        {class:"hs-chip-label","text-anchor":"middle","font-size":fs*0.72,fill:vc}));
      mapG.appendChild(g);
    });
  }
  S.appendChild(mapG);

  if(showLegend){
    // Tick labels are right-aligned to the left of the bar, so the bar has
    // to sit far enough in for the widest of them to fit on the slide.
    const tickRoom = fs*0.62*(String(fmtNum(hi,el)).length*0.62+1.6);
    S.appendChild(buildLegend(el,stops,lo,hi,VW,VH,{
      x:num(el.legendX, Math.max(tickRoom, 34)), y:num(el.legendY,VH*0.20),
      w:num(el.legendW,26), h:num(el.legendH,VH*0.48)
    }));
  }

  if(el.title){
    const t=svgText(gutter+mw/2, fs*1.5, el.title, {class:"hs-title","text-anchor":"middle","font-size":fs*1.35});
    if(el.titleColor)t.setAttribute("fill",el.titleColor);
    S.appendChild(t);
  }
  box.appendChild(S);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   2. GRADIENT LEGEND — the same scale, on its own
   ════════════════════════════════════════════════════════════════════ */
function renderGradientLegend(el){
  const box=div("hs-box hs-legend-box"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#1d4e89");
  const {VW,VH}=viewBox(el,420,0.6,4);
  const S=svg("svg",{viewBox:`0 0 ${VW} ${VH}`,preserveAspectRatio:"xMidYMid meet",class:"hs-svg"});
  const stops=rampFor(el);
  const lo=num(el.scaleMin,0), hi=num(el.scaleMax,100);
  S.appendChild(buildLegend(el,stops,lo,hi,VW,VH,{
    x:num(el.legendX,VW*0.42), y:VH*0.12, w:num(el.legendW,34), h:VH*0.76
  }));
  box.appendChild(S);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   3. STAT BLOCK — one number that has to land
   ════════════════════════════════════════════════════════════════════ */
function renderStatBlock(el){
  const box=div("hs-box hs-stat"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#e8482b");
  const r=rows(el)[0]||{label:el.title||"Metric",value:num(el.level,0),note:""};
  const align=el.textAlign||"left";
  box.style.setProperty("--align",align);
  box.classList.add("hs-align-"+align);

  if(el.title) box.appendChild(div("hs-stat-kicker",el.title));
  const v=div("hs-stat-value");
  v.textContent=fmtNum(r.value,el);
  if(el.numberMode==="countup") v.dataset.countTo=String(r.value);
  box.appendChild(v);
  if(r.label) box.appendChild(div("hs-stat-label",r.label));
  if(r.value2!=null){
    const up=r.value2>=0;
    const d=div("hs-stat-delta "+(up?"up":"down"));
    d.textContent=(up?"▲ ":"▼ ")+fmtNum(Math.abs(r.value2),el);
    box.appendChild(d);
  }
  if(r.note) box.appendChild(div("hs-stat-note",r.note));
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   4. KPI GRID — a row or grid of stat tiles
   ════════════════════════════════════════════════════════════════════ */
function renderKpiGrid(el){
  const box=div("hs-box hs-kpi"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#1d4e89");
  const data=rows(el);
  const cols=clamp(num(el.cols,Math.min(3,Math.max(1,data.length))),1,6);
  const grid=div("hs-kpi-grid");
  grid.style.gridTemplateColumns=`repeat(${cols},minmax(0,1fr))`;
  const stops=rampFor(el);
  if(el.title) box.appendChild(div("hs-block-title",el.title));
  data.forEach((r,i)=>{
    const c=r.color||(el.tintTiles!==false?seriesColor(stops,i,data.length):(el.accent||"#1d4e89"));
    const tile=div("hs-kpi-tile hs-kpi-"+(el.tileStyle||"soft"));
    tile.style.setProperty("--tint",c);
    tile.style.setProperty("--i",i);
    if((el.tileStyle||"soft")==="solid") tile.style.setProperty("--ink",readable(c));
    const v=div("hs-kpi-value",fmtNum(r.value,el));
    if(el.numberMode==="countup") v.dataset.countTo=String(r.value);
    tile.appendChild(v);
    if(r.label) tile.appendChild(div("hs-kpi-label",r.label));
    if(r.note)  tile.appendChild(div("hs-kpi-note",r.note));
    grid.appendChild(tile);
  });
  box.appendChild(grid);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   5. BULLET BARS — actual against target
   ════════════════════════════════════════════════════════════════════ */
function renderBulletBars(el){
  const box=div("hs-box hs-bullet"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#0d9488");
  const data=rows(el);
  const hi=el.max!=null&&el.max!==""?num(el.max,100):Math.max(1,...data.map(r=>Math.max(r.value,r.value2||0)))*1.08;
  if(el.title) box.appendChild(div("hs-block-title",el.title));
  const list=div("hs-bullet-list");
  const stops=rampFor(el);
  data.forEach((r,i)=>{
    const row=div("hs-bullet-row");
    row.style.setProperty("--i",i);
    row.appendChild(div("hs-bullet-label",r.label));
    const track=div("hs-bullet-track");
    const fill=div("hs-bullet-fill");
    fill.style.width=clamp(r.value/hi*100,0,100)+"%";
    fill.style.background=r.color||seriesColor(stops,i,data.length);
    track.appendChild(fill);
    if(r.value2!=null){
      const tgt=div("hs-bullet-target");
      tgt.style.left=clamp(r.value2/hi*100,0,100)+"%";
      tgt.title="Target "+fmtNum(r.value2,el);
      track.appendChild(tgt);
    }
    row.appendChild(track);
    if(el.showValues!==false) row.appendChild(div("hs-bullet-value",fmtNum(r.value,el)));
    list.appendChild(row);
  });
  box.appendChild(list);
  if(el.legendNote!==false && data.some(r=>r.value2!=null)){
    box.appendChild(div("hs-bullet-key","▎ target"));
  }
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   6. SLOPE CHART — before → after, one line per item
   ════════════════════════════════════════════════════════════════════ */
function renderSlope(el){
  const box=div("hs-box hs-slope"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#7c3aed");
  const data=rows(el).filter(r=>r.value2!=null);
  const {VW,VH}=viewBox(el,1000,0.45,1.3);
  const S=svg("svg",{viewBox:`0 0 ${VW} ${VH}`,preserveAspectRatio:"xMidYMid meet",class:"hs-svg"});
  const fs=num(el.labelSize,24);
  const padT=el.title?fs*3:fs*2.4, padB=fs*2.6;
  const lx=VW*0.30, rx=VW*0.70;
  const all=data.map(r=>r.value).concat(data.map(r=>r.value2));
  let lo=Math.min.apply(null,all), hi=Math.max.apply(null,all);
  if(!isFinite(lo)){lo=0;hi=1;} if(lo===hi){hi=lo+1;}
  const yOf=v=>padT+(VH-padT-padB)*(1-(v-lo)/(hi-lo));
  const stops=rampFor(el);

  S.appendChild(svg("line",{x1:lx,y1:padT,x2:lx,y2:VH-padB,stroke:"rgba(15,23,42,.16)","stroke-width":2}));
  S.appendChild(svg("line",{x1:rx,y1:padT,x2:rx,y2:VH-padB,stroke:"rgba(15,23,42,.16)","stroke-width":2}));
  S.appendChild(svgText(lx,VH-padB+fs*1.5,el.leftLabel||"Before",{class:"hs-axis","text-anchor":"middle","font-size":fs*0.85}));
  S.appendChild(svgText(rx,VH-padB+fs*1.5,el.rightLabel||"After",{class:"hs-axis","text-anchor":"middle","font-size":fs*0.85}));

  data.forEach((r,i)=>{
    const c=r.color||seriesColor(stops,i,data.length);
    const y1=yOf(r.value), y2=yOf(r.value2);
    const g=svg("g",{class:"hs-slope-item",style:`--i:${i}`});
    g.appendChild(svg("line",{x1:lx,y1,x2:rx,y2,stroke:c,"stroke-width":num(el.lineW,4),"stroke-linecap":"round"}));
    g.appendChild(svg("circle",{cx:lx,cy:y1,r:num(el.dotR,8),fill:c}));
    g.appendChild(svg("circle",{cx:rx,cy:y2,r:num(el.dotR,8),fill:c}));
    g.appendChild(svgText(lx-fs*0.9,y1+fs*0.34,r.label+"  "+fmtNum(r.value,el),{class:"hs-slope-label","text-anchor":"end","font-size":fs*0.82,fill:c}));
    g.appendChild(svgText(rx+fs*0.9,y2+fs*0.34,fmtNum(r.value2,el),{class:"hs-slope-label","font-size":fs*0.82,fill:c}));
    S.appendChild(g);
  });
  if(el.title) S.appendChild(svgText(VW/2,fs*1.6,el.title,{class:"hs-title","text-anchor":"middle","font-size":fs*1.3}));
  box.appendChild(S);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   7. WAFFLE — 100 cells, one share of the whole
   ════════════════════════════════════════════════════════════════════ */
function renderWaffle(el){
  const box=div("hs-box hs-waffle"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#0284c7");
  const cols=clamp(num(el.cols,10),2,20), total=cols*cols;
  const data=rows(el);
  const stops=rampFor(el);
  // Multi-row waffles apportion cells by share of the sum; a single row is
  // read as a straight percentage.
  let cells=[];
  if(data.length<=1){
    const pct=clamp(data.length?data[0].value:num(el.level,60),0,100);
    const on=Math.round(pct/100*total);
    cells=Array.from({length:total},(_,i)=>i<on?(data[0]&&data[0].color)||el.accent||"#0284c7":null);
  } else {
    const sum=data.reduce((s,r)=>s+Math.max(0,r.value),0)||1;
    let acc=[];
    data.forEach((r,i)=>{
      const n=Math.round(Math.max(0,r.value)/sum*total);
      const c=r.color||seriesColor(stops,i,data.length);
      for(let k=0;k<n;k++)acc.push(c);
    });
    cells=Array.from({length:total},(_,i)=>acc[i]||null);
  }
  if(el.title) box.appendChild(div("hs-block-title",el.title));
  const grid=div("hs-waffle-grid");
  grid.style.gridTemplateColumns=`repeat(${cols},1fr)`;
  cells.forEach((c,i)=>{
    const cell=div("hs-waffle-cell"+(c?" on":""));
    cell.style.setProperty("--i",i);
    if(c)cell.style.background=c;
    if(el.shape==="circle")cell.style.borderRadius="50%";
    grid.appendChild(cell);
  });
  box.appendChild(grid);
  if(el.showValues!==false){
    const key=div("hs-waffle-key");
    (data.length?data:[{label:el.label||"Share",value:num(el.level,60),color:el.accent}]).forEach((r,i)=>{
      const k=div("hs-key-item");
      const sw=div("hs-key-swatch");
      sw.style.background=r.color||seriesColor(stops,i,data.length);
      k.appendChild(sw); k.appendChild(div("hs-key-text",r.label+" · "+fmtNum(r.value,el)));
      key.appendChild(k);
    });
    box.appendChild(key);
  }
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   8. RING GRID — several percentage donuts side by side
   ════════════════════════════════════════════════════════════════════ */
function renderRingGrid(el){
  const box=div("hs-box hs-rings"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#16a34a");
  const data=rows(el);
  const cols=clamp(num(el.cols,Math.min(4,Math.max(1,data.length))),1,6);
  if(el.title) box.appendChild(div("hs-block-title",el.title));
  const grid=div("hs-ring-grid");
  grid.style.gridTemplateColumns=`repeat(${cols},minmax(0,1fr))`;
  const stops=rampFor(el);
  const thick=clamp(num(el.ringW,13),4,34);
  data.forEach((r,i)=>{
    const c=r.color||seriesColor(stops,i,data.length);
    const cell=div("hs-ring-cell"); cell.style.setProperty("--i",i);
    const R=50-thick/2, C=2*Math.PI*R;
    const pct=clamp(r.value,0,num(el.max,100))/Math.max(1,num(el.max,100));
    const S=svg("svg",{viewBox:"0 0 100 100",class:"hs-ring-svg"});
    S.appendChild(svg("circle",{cx:50,cy:50,r:R,fill:"none",stroke:el.dark?"rgba(255,255,255,.12)":"rgba(15,23,42,.10)","stroke-width":thick}));
    const arc=svg("circle",{cx:50,cy:50,r:R,fill:"none",stroke:c,"stroke-width":thick,"stroke-linecap":el.ringCap||"round",
      "stroke-dasharray":C.toFixed(2),"stroke-dashoffset":(C*(1-pct)).toFixed(2),transform:"rotate(-90 50 50)",class:"hs-ring-arc"});
    S.appendChild(arc);
    S.appendChild(svgText(50,50+num(el.labelSize,22)*0.34,fmtNum(r.value,el),
      {class:"hs-ring-value","text-anchor":"middle","font-size":num(el.labelSize,22),fill:el.dark?"#fff":"#0f172a"}));
    cell.appendChild(S);
    if(r.label)cell.appendChild(div("hs-ring-label",r.label));
    if(r.note)cell.appendChild(div("hs-ring-note",r.note));
    grid.appendChild(cell);
  });
  box.appendChild(grid);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   9. PROCESS STEPS — numbered chevrons or cards
   ════════════════════════════════════════════════════════════════════ */
function renderProcessSteps(el){
  const box=div("hs-box hs-steps"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#1d4e89");
  const data=rows(el);
  const stops=rampFor(el);
  const vertical=el.orient==="vertical";
  if(el.title) box.appendChild(div("hs-block-title",el.title));
  const track=div("hs-steps-track"+(vertical?" vertical":"")+" hs-steps-"+(el.stepStyle||"chevron"));
  data.forEach((r,i)=>{
    const c=r.color||seriesColor(stops,i,data.length);
    const step=div("hs-step");
    step.style.setProperty("--tint",c);
    step.style.setProperty("--ink",readable(c));
    step.style.setProperty("--i",i);
    if(el.showNumbers!==false) step.appendChild(div("hs-step-num",String(i+1)));
    const body=div("hs-step-body");
    body.appendChild(div("hs-step-label",r.label));
    if(r.note)body.appendChild(div("hs-step-note",r.note));
    if(r.value)body.appendChild(div("hs-step-value",fmtNum(r.value,el)));
    step.appendChild(body);
    track.appendChild(step);
  });
  box.appendChild(track);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   10. TIMELINE — milestones along an axis
   ════════════════════════════════════════════════════════════════════ */
function renderTimeline(el){
  const box=div("hs-box hs-timeline"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#0d9488");
  const data=rows(el);
  const stops=rampFor(el);
  if(el.title) box.appendChild(div("hs-block-title",el.title));
  const vertical=el.orient==="vertical";
  const track=div("hs-tl-track"+(vertical?" vertical":""));
  data.forEach((r,i)=>{
    const c=r.color||seriesColor(stops,i,data.length);
    const node=div("hs-tl-node"+(el.alternate!==false&&!vertical&&i%2?" below":""));
    node.style.setProperty("--tint",c);
    node.style.setProperty("--i",i);
    node.appendChild(div("hs-tl-dot"));
    const card=div("hs-tl-card");
    card.appendChild(div("hs-tl-when",r.label));
    if(r.note)card.appendChild(div("hs-tl-what",r.note));
    if(r.value)card.appendChild(div("hs-tl-value",fmtNum(r.value,el)));
    node.appendChild(card);
    track.appendChild(node);
  });
  box.appendChild(track);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   11. RANKED BARS — a sorted league table you can read from the back row
   ════════════════════════════════════════════════════════════════════ */
function renderRankBars(el){
  const box=div("hs-box hs-rank"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#e8482b");
  let data=rows(el);
  if(el.sort==="desc") data=data.slice().sort((a,b)=>b.value-a.value);
  else if(el.sort==="asc") data=data.slice().sort((a,b)=>a.value-b.value);
  const hi=el.max!=null&&el.max!==""?num(el.max,100):Math.max(1,...data.map(r=>r.value));
  const stops=rampFor(el);
  if(el.title) box.appendChild(div("hs-block-title",el.title));
  const list=div("hs-rank-list");
  data.forEach((r,i)=>{
    const c=r.color||seriesColor(stops,data.length-1-i,data.length);
    const row=div("hs-rank-row"); row.style.setProperty("--i",i);
    if(el.showNumbers!==false) row.appendChild(div("hs-rank-pos",String(i+1)));
    row.appendChild(div("hs-rank-label",r.label));
    const track=div("hs-rank-track");
    const fill=div("hs-rank-fill");
    fill.style.width=clamp(r.value/hi*100,0,100)+"%";
    fill.style.background=c;
    track.appendChild(fill);
    row.appendChild(track);
    if(el.showValues!==false) row.appendChild(div("hs-rank-value",fmtNum(r.value,el)));
    list.appendChild(row);
  });
  box.appendChild(list);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   12. 2×2 MATRIX — plot items against two axes
   ════════════════════════════════════════════════════════════════════ */
function renderMatrix(el){
  const box=div("hs-box hs-matrix"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#7c3aed");
  const {VW,VH}=viewBox(el,1000,0.6,1.2);
  const S=svg("svg",{viewBox:`0 0 ${VW} ${VH}`,preserveAspectRatio:"xMidYMid meet",class:"hs-svg"});
  const fs=num(el.labelSize,24);
  const pad=fs*3.2;
  const x0=pad,y0=el.title?fs*3:pad, x1=VW-pad, y1=VH-pad;
  const cx=(x0+x1)/2, cy=(y0+y1)/2;
  const stops=rampFor(el);
  const quad=[el.q1||"",el.q2||"",el.q3||"",el.q4||""];
  const tints=[rampAt(stops,.14),rampAt(stops,.30),rampAt(stops,.46),rampAt(stops,.62)];
  [[x0,y0,cx,cy,0],[cx,y0,x1,cy,1],[x0,cy,cx,y1,2],[cx,cy,x1,y1,3]].forEach(([a,b,c,d,i])=>{
    S.appendChild(svg("rect",{x:a,y:b,width:c-a,height:d-b,fill:tints[i],opacity:.55}));
    if(quad[i]) S.appendChild(svgText((a+c)/2,b+fs*1.6,quad[i],{class:"hs-quad","text-anchor":"middle","font-size":fs*0.82}));
  });
  S.appendChild(svg("line",{x1:cx,y1:y0,x2:cx,y2:y1,stroke:"rgba(15,23,42,.28)","stroke-width":2}));
  S.appendChild(svg("line",{x1:x0,y1:cy,x2:x1,y2:cy,stroke:"rgba(15,23,42,.28)","stroke-width":2}));
  S.appendChild(svg("rect",{x:x0,y:y0,width:x1-x0,height:y1-y0,fill:"none",stroke:"rgba(15,23,42,.22)","stroke-width":2,rx:10}));

  // value = x (0–100), value2 = y (0–100)
  rows(el).forEach((r,i)=>{
    const px=x0+(x1-x0)*clamp(r.value,0,100)/100;
    const py=y1-(y1-y0)*clamp(r.value2==null?50:r.value2,0,100)/100;
    const c=r.color||rampAt(stops,.72);
    const g=svg("g",{class:"hs-matrix-dot",style:`--i:${i}`});
    g.appendChild(svg("circle",{cx:px,cy:py,r:num(el.dotR,13),fill:c,stroke:"#fff","stroke-width":3}));
    g.appendChild(svgText(px,py-num(el.dotR,13)-fs*0.5,r.label,{class:"hs-matrix-label","text-anchor":"middle","font-size":fs*0.76}));
    S.appendChild(g);
  });
  S.appendChild(svgText((x0+x1)/2,y1+fs*1.7,el.xLabel||"",{class:"hs-axis","text-anchor":"middle","font-size":fs*0.82}));
  const yl=svgText(0,0,el.yLabel||"",{class:"hs-axis","text-anchor":"middle","font-size":fs*0.82,transform:`translate(${x0-fs*1.7},${(y0+y1)/2}) rotate(-90)`});
  S.appendChild(yl);
  if(el.title) S.appendChild(svgText(VW/2,fs*1.6,el.title,{class:"hs-title","text-anchor":"middle","font-size":fs*1.3}));
  box.appendChild(S);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   13. VENN — two or three overlapping sets
   ════════════════════════════════════════════════════════════════════ */
function renderVenn(el){
  const box=div("hs-box hs-venn"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#0284c7");
  const data=rows(el).slice(0,3);
  const {VW,VH}=viewBox(el,1000,0.6,1.1);
  const S=svg("svg",{viewBox:`0 0 ${VW} ${VH}`,preserveAspectRatio:"xMidYMid meet",class:"hs-svg"});
  const fs=num(el.labelSize,26);
  const stops=rampFor(el);
  const R=Math.min(VW,VH)*num(el.circleR,0.27);
  const cy=VH*(el.title?0.56:0.5);
  const centres = data.length>=3
    ? [[VW/2-R*0.62,cy-R*0.34],[VW/2+R*0.62,cy-R*0.34],[VW/2,cy+R*0.66]]
    : [[VW/2-R*0.55,cy],[VW/2+R*0.55,cy]];
  data.forEach((r,i)=>{
    const c=r.color||seriesColor(stops,i,data.length);
    const g=svg("g",{class:"hs-venn-set",style:`--i:${i}`});
    g.appendChild(svg("circle",{cx:centres[i][0],cy:centres[i][1],r:R,fill:c,opacity:num(el.circleOpacity,.55),
      stroke:c,"stroke-width":3,style:"mix-blend-mode:multiply"}));
    S.appendChild(g);
  });
  data.forEach((r,i)=>{
    const [px,py]=centres[i];
    const off = data.length>=3 ? (i===2?R*0.52:-R*0.52) : 0;
    const lx = data.length>=3 ? px : px+(i===0?-R*0.42:R*0.42);
    S.appendChild(svgText(lx,py+off,r.label,{class:"hs-venn-label","text-anchor":"middle","font-size":fs*0.9,fill:el.dark?"#fff":"#0f172a"}));
    if(r.value) S.appendChild(svgText(lx,py+off+fs*1.1,fmtNum(r.value,el),{class:"hs-venn-value","text-anchor":"middle","font-size":fs*0.78,fill:el.dark?"#e2e8f0":"#334155"}));
  });
  if(el.centerLabel) S.appendChild(svgText(VW/2,data.length>=3?cy+R*0.08:cy,el.centerLabel,
    {class:"hs-venn-center","text-anchor":"middle","font-size":fs*0.82,fill:"#0f172a"}));
  if(el.title) S.appendChild(svgText(VW/2,fs*1.6,el.title,{class:"hs-title","text-anchor":"middle","font-size":fs*1.3}));
  box.appendChild(S);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   14. PYRAMID — tiers, widest at the base (or inverted)
   ════════════════════════════════════════════════════════════════════ */
function renderPyramid(el){
  const box=div("hs-box hs-pyramid"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#ea580c");
  const data=rows(el);
  const {VW,VH}=viewBox(el,1000,0.55,1.25);
  const S=svg("svg",{viewBox:`0 0 ${VW} ${VH}`,preserveAspectRatio:"xMidYMid meet",class:"hs-svg"});
  const fs=num(el.labelSize,26);
  const top=el.title?fs*3.2:fs*1.2, bottom=VH-fs*1.2;
  const n=Math.max(1,data.length);
  const gap=num(el.tierGap,6);
  const th=(bottom-top-gap*(n-1))/n;
  const stops=rampFor(el);
  const inverted=el.inverted===true;
  const maxHalf=VW*num(el.baseWidth,0.34);
  const minHalf=maxHalf*num(el.apexRatio,0.14);

  // Tier i counts down from the top of the drawing. A normal pyramid is
  // narrowest at i=0 and widest at the base; an inverted one (a funnel) is
  // the other way round. Each tier's top and bottom half-widths are just
  // the ramp sampled at i/n and (i+1)/n.
  const halfAt = f => minHalf+(maxHalf-minHalf)*clamp(f,0,1);
  data.forEach((r,i)=>{
    const y=top+i*(th+gap);
    const fTop = inverted ? 1-(i/n)     : i/n;
    const fBot = inverted ? 1-((i+1)/n) : (i+1)/n;
    const wTop=halfAt(fTop), wBot=halfAt(fBot);
    const c=r.color||seriesColor(stops,i,n);
    const cx=VW*num(el.centerX,0.42);
    const g=svg("g",{class:"hs-pyr-tier",style:`--i:${i}`});
    g.appendChild(svg("path",{
      d:`M ${cx-wTop} ${y} L ${cx+wTop} ${y} L ${cx+wBot} ${y+th} L ${cx-wBot} ${y+th} Z`,
      fill:c, stroke:el.dark?"rgba(255,255,255,.16)":"#fff","stroke-width":2
    }));
    g.appendChild(svgText(cx,y+th/2+fs*0.34,r.label,{class:"hs-pyr-label","text-anchor":"middle","font-size":fs*0.82,fill:readable(c)}));
    if(el.showValues!==false && r.value){
      g.appendChild(svgText(cx+maxHalf+fs*0.8,y+th/2+fs*0.3,fmtNum(r.value,el),
        {class:"hs-pyr-value","font-size":fs*0.84,fill:c}));
    }
    if(r.note) g.appendChild(svgText(cx+maxHalf+fs*0.8,y+th/2+fs*1.3,r.note,
      {class:"hs-pyr-note","font-size":fs*0.62,fill:el.dark?"#cbd5e1":"#64748b"}));
    S.appendChild(g);
  });
  if(el.title) S.appendChild(svgText(VW/2,fs*1.7,el.title,{class:"hs-title","text-anchor":"middle","font-size":fs*1.3}));
  box.appendChild(S);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   15. SANKEY — one source splitting into destinations
   ────────────────────────────────────────────────────────────────────
   A two-stage flow, which is the shape almost every slide actually needs:
   a budget, a funnel, an energy mix. Ribbon thickness is proportional to
   value; the ribbons are cubic curves so they read cleanly at distance.
   ════════════════════════════════════════════════════════════════════ */
function renderSankey(el){
  const box=div("hs-box hs-sankey"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#0d9488");
  const data=rows(el);
  const {VW,VH}=viewBox(el,1000,0.45,1.15);
  const S=svg("svg",{viewBox:`0 0 ${VW} ${VH}`,preserveAspectRatio:"xMidYMid meet",class:"hs-svg"});
  const fs=num(el.labelSize,24);
  const top=el.title?fs*3.2:fs*1.4, bottom=VH-fs*1.4;
  const total=data.reduce((s,r)=>s+Math.max(0,r.value),0)||1;
  const stops=rampFor(el);
  const nodeW=num(el.nodeW,26);
  // The source label is right-aligned to the left of the source node, so
  // the node needs enough of a gutter for that text to stay on the slide.
  const srcX=VW*0.30, dstX=VW*0.68;
  const gap=num(el.flowGap,8);
  const span=bottom-top;
  const dstSpan=span-gap*Math.max(0,data.length-1);

  // source node
  S.appendChild(svg("rect",{x:srcX-nodeW,y:top,width:nodeW,height:span,rx:5,fill:el.accent||"#0d9488"}));
  S.appendChild(svgText(srcX-nodeW-fs*0.7,top+span/2,el.sourceLabel||"Total",
    {class:"hs-sankey-src","text-anchor":"end","font-size":fs*0.92,fill:el.dark?"#fff":"#0f172a"}));
  S.appendChild(svgText(srcX-nodeW-fs*0.7,top+span/2+fs*1.15,fmtNum(total,el),
    {class:"hs-sankey-srcv","text-anchor":"end","font-size":fs*0.78,fill:el.dark?"#94a3b8":"#64748b"}));

  let sy=top, dy=top;
  data.forEach((r,i)=>{
    const share=Math.max(0,r.value)/total;
    const sh=span*share, dh=dstSpan*share;
    const c=r.color||seriesColor(stops,i,data.length);
    const mx=(srcX+dstX)/2;
    const d=`M ${srcX} ${sy} C ${mx} ${sy}, ${mx} ${dy}, ${dstX} ${dy}
             L ${dstX} ${dy+dh} C ${mx} ${dy+dh}, ${mx} ${sy+sh}, ${srcX} ${sy+sh} Z`;
    const g=svg("g",{class:"hs-sankey-flow",style:`--i:${i}`});
    g.appendChild(svg("path",{d,fill:c,opacity:num(el.flowOpacity,.62)}));
    g.appendChild(svg("rect",{x:dstX,y:dy,width:nodeW,height:dh,rx:5,fill:c}));
    g.appendChild(svgText(dstX+nodeW+fs*0.6,dy+dh/2+fs*0.14,r.label,
      {class:"hs-sankey-label","font-size":fs*0.82,fill:el.dark?"#e2e8f0":"#0f172a"}));
    if(el.showValues!==false){
      g.appendChild(svgText(dstX+nodeW+fs*0.6,dy+dh/2+fs*1.06,
        fmtNum(r.value,el)+(el.showShare!==false?"  ·  "+Math.round(share*100)+"%":""),
        {class:"hs-sankey-value","font-size":fs*0.66,fill:c}));
    }
    S.appendChild(g);
    sy+=sh; dy+=dh+gap;
  });
  if(el.title) S.appendChild(svgText(VW/2,fs*1.7,el.title,{class:"hs-title","text-anchor":"middle","font-size":fs*1.3}));
  box.appendChild(S);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   16. HEAT GRID — a labelled matrix
   ────────────────────────────────────────────────────────────────────
   Rows here carry the whole matrix: `label` is the row name and `note`
   holds the comma-separated cell values, so one data grid still drives it.
   Column names come from el.colLabels.
   ════════════════════════════════════════════════════════════════════ */
function renderHeatGrid(el){
  const box=div("hs-box hs-heat"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#0284c7");
  const data=rows(el);
  const cells=data.map(r=>String(r.note||"").split(/[,;\s]+/).filter(Boolean).map(Number));
  const cols=Math.max(1,...cells.map(c=>c.length));
  const colLabels=String(el.colLabels||"").split(/[,;]/).map(s=>s.trim());
  const flat=cells.flat().filter(isFinite);
  let lo=el.scaleMin!=null&&el.scaleMin!==""?num(el.scaleMin,0):Math.min.apply(null,flat.concat([Infinity]));
  let hi=el.scaleMax!=null&&el.scaleMax!==""?num(el.scaleMax,100):Math.max.apply(null,flat.concat([-Infinity]));
  if(!isFinite(lo)||!isFinite(hi)||lo===hi){lo=0;hi=Math.max(1,isFinite(hi)?hi:100);}
  const stops=rampFor(el);
  if(el.title) box.appendChild(div("hs-block-title",el.title));
  const table=document.createElement("table");
  table.className="hs-heat-table";
  if(colLabels.filter(Boolean).length){
    const tr=document.createElement("tr");
    tr.appendChild(document.createElement("th"));
    for(let c=0;c<cols;c++){
      const th=document.createElement("th");
      th.textContent=colLabels[c]||"";
      tr.appendChild(th);
    }
    table.appendChild(tr);
  }
  data.forEach((r,ri)=>{
    const tr=document.createElement("tr");
    const th=document.createElement("th");
    th.className="hs-heat-row-label"; th.textContent=r.label;
    tr.appendChild(th);
    for(let c=0;c<cols;c++){
      const v=cells[ri][c];
      const td=document.createElement("td");
      if(isFinite(v)){
        const t=clamp((v-lo)/Math.max(1e-9,(hi-lo)),0,1);
        const bg=rampAt(stops,t);
        td.style.background=bg;
        td.style.color=readable(bg);
        td.textContent=el.showValues===false?"":fmtNum(v,el);
      } else { td.className="hs-heat-empty"; }
      td.style.setProperty("--i",ri*cols+c);
      tr.appendChild(td);
    }
    table.appendChild(tr);
  });
  box.appendChild(table);
  return box;
}

/* ════════════════════════════════════════════════════════════════════
   17. QUOTE CARD — a pull quote with attribution
   ════════════════════════════════════════════════════════════════════ */
function renderQuoteCard(el){
  const box=div("hs-box hs-quote"+(el.dark?" hs-dark":"")+(el.hideContainer?" hs-bare":""));
  box.style.setProperty("--accent", el.accent||"#7c3aed");
  box.classList.add("hs-quote-"+(el.quoteStyle||"bar"));
  const r=rows(el)[0]||{label:"",note:""};
  if(el.showMark!==false) box.appendChild(div("hs-quote-mark","\u201C"));
  const q=div("hs-quote-text", el.quote || r.label || "Your quotation goes here.");
  if(el.quoteSize) q.style.fontSize=num(el.quoteSize,34)+"px";
  box.appendChild(q);
  const who=el.attribution||r.note||"";
  if(who) box.appendChild(div("hs-quote-attr", who));
  if(el.role) box.appendChild(div("hs-quote-role", el.role));
  return box;
}

