const STUDIO_KINDS = Object.keys(STUDIO);
STUDIO_KINDS.forEach(k=>{ SEED[k]=STUDIO[k].seed||{}; });

/* ── 1. the Objects drawer ──────────────────────────────────────── */
STUDIO_KINDS.forEach(k=>{
  if(!OBJECTS.some(o=>o.kind===k)) OBJECTS.push(STUDIO[k].def);
});

/* ── 2. the render hook ─────────────────────────────────────────────
   hanns_core.js renderObject() asks HannsActors whether it owns a kind
   and, if so, delegates. It asks at render time, so wrapping the object
   here — after core has loaded — is enough to own new kinds outright. */
const prevActors = window.HannsActors || {};
window.HannsActors = Object.assign({}, prevActors, {
  ACTOR_KINDS:    prevActors.ACTOR_KINDS    || new Set(),
  ACTOR_ACTIONS:  prevActors.ACTOR_ACTIONS  || {},
  ACTOR_HAS_MOOD: prevActors.ACTOR_HAS_MOOD || new Set(),
  ACTOR_HAS_LEVEL:prevActors.ACTOR_HAS_LEVEL|| new Set(),
  isActor(kind){
    return !!STUDIO[kind] || !!(prevActors.isActor && prevActors.isActor(kind));
  },
  renderActor(el){
    const s=STUDIO[el&&el.objectType];
    if(s){
      try{ return s.render(el); }
      catch(err){
        console.error("[hanns-studio] render failed for "+el.objectType, err);
        const b=div("hs-box hs-error","⚠ "+el.objectType+" could not be drawn — check its data.");
        return b;
      }
    }
    return prevActors.renderActor ? prevActors.renderActor(el) : div("hs-box","");
  },
  playActorOnce(node,kind,ms){
    if(STUDIO[kind]) return;
    if(prevActors.playActorOnce) prevActors.playActorOnce(node,kind,ms);
  },
});

/* ── 3. seed a fresh element with real sample data ──────────────────
   hanns_editor.js destructures makeObject from window.Hanns when it
   loads, which is after this file, so the wrapper is the one it gets.
   A new choropleth therefore arrives with eight countries on it rather
   than as an empty frame. */
const coreMakeObject = Hx.makeObject;
Hx.makeObject = function(kind, over){
  const el = coreMakeObject(kind, over||{});
  const s = STUDIO[kind];
  if(s && s.seed){
    for(const k in s.seed){
      if(el[k]===undefined) el[k]=JSON.parse(JSON.stringify(s.seed[k]));
    }
    if(over) Object.assign(el, over);
  }
  return el;
};

